examples.template:
HStack {
    Text({{rowLabel}}).monarchTextStyle(.body)
    Spacer()
    Button {
        isOpen = true
    } label: {
        MonarchIcon(systemName: "ellipsis", label: "Actions for " + {{rowLabel}})
            .monarchMinimumHitTarget()
    }
    .buttonStyle(.monarch(.ghost, size: .sm))
    .onAppear { if startsPresented { isOpen = true } }
    .popover(isPresented: $isOpen, arrowEdge: .top) {
        VStack(alignment: .leading, spacing: 0) {
            Button {
                isOpen = false
            } label: {
                Text({{actions.0.label}}).monarchTextStyle(.body).frame(maxWidth: .infinity, alignment: .leading).frame(minHeight: 44).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            Button {
                isOpen = false
            } label: {
                HStack {
                    Text({{actions.1.label}}).monarchTextStyle(.body)
                    Spacer(minLength: theme.spacing.space4)
                    Text({{actions.1.shortcut}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                }
                .frame(minHeight: 44).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            MonarchDivider()
            Button {
                isOpen = false
                isConfirming = true
            } label: {
                Text({{actions.2.label}}).monarchTextStyle(.body).foregroundStyle({{actions.2.tone}} == "danger" ? theme.colors.dangerStrong : theme.colors.textDefault).frame(maxWidth: .infinity, alignment: .leading).frame(minHeight: 44).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal, theme.spacing.space3)
        .frame(minWidth: 200)
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgSurface)
    }
}
.confirmationDialog(
    {{actions.2.confirm.title}},
    isPresented: $isConfirming,
    titleVisibility: .visible,
    actions: {
        Button({{actions.2.confirm.confirmLabel}}, role: .destructive) { isDeleted = true }
        Button("Cancel", role: .cancel) {}
    },
    message: { Text({{actions.2.confirm.description}}) }
)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@Environment(\.monarchStartsPresented) private var startsPresented
@State private var isOpen = false
@State private var isConfirming = false
@State private var isDeleted = false

examples.setup:
@Environment(\.monarchTheme) private var theme
@Environment(\.monarchStartsPresented) private var startsPresented
@State private var isOpen = false
@State private var isConfirming = false
@State private var isDeleted = false

examples.code:
HStack {
    Text("Report 12").monarchTextStyle(.body)
    Spacer()
    Button {
        isOpen = true
    } label: {
        MonarchIcon(systemName: "ellipsis", label: "Actions for " + "Report 12")
            .monarchMinimumHitTarget()
    }
    .buttonStyle(.monarch(.ghost, size: .sm))
    .onAppear { if startsPresented { isOpen = true } }
    .popover(isPresented: $isOpen, arrowEdge: .top) {
        VStack(alignment: .leading, spacing: 0) {
            Button {
                isOpen = false
            } label: {
                Text("Open").monarchTextStyle(.body).frame(maxWidth: .infinity, alignment: .leading).frame(minHeight: 44).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            Button {
                isOpen = false
            } label: {
                HStack {
                    Text("Rename").monarchTextStyle(.body)
                    Spacer(minLength: theme.spacing.space4)
                    Text("F2").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                }
                .frame(minHeight: 44).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            MonarchDivider()
            Button {
                isOpen = false
                isConfirming = true
            } label: {
                Text("Delete").monarchTextStyle(.body).foregroundStyle("danger" == "danger" ? theme.colors.dangerStrong : theme.colors.textDefault).frame(maxWidth: .infinity, alignment: .leading).frame(minHeight: 44).contentShape(Rectangle())
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal, theme.spacing.space3)
        .frame(minWidth: 200)
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgSurface)
    }
}
.confirmationDialog(
    "Delete Report 12?",
    isPresented: $isConfirming,
    titleVisibility: .visible,
    actions: {
        Button("Delete report", role: .destructive) { isDeleted = true }
        Button("Cancel", role: .cancel) {}
    },
    message: { Text("The report and its history are removed.") }
)

List(companies, id: \.self) { company in
    Text(company)
        .monarchTextStyle(.body)
        .swipeActions(edge: .trailing) {
            Button("Delete", systemImage: "trash", role: .destructive) {
                companies.removeAll { $0 == company }
            }
            Button("Archive", systemImage: "archivebox") {}
        }
        .contextMenu {
            Button("Archive", systemImage: "archivebox") {}
            Divider()
            Button("Delete", systemImage: "trash", role: .destructive) {
                companies.removeAll { $0 == company }
            }
        }
}
.listStyle(.plain)
.monarchCanvas()
